import sys
from collections import deque

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    out_lines = []

    for _ in range(T):
        try:
            N = int(next(iterator))
            M = int(next(iterator))
        except StopIteration:
            break

        adj = [set() for _ in range(N + 1)]

        for _ in range(M):
            u = int(next(iterator))
            v = int(next(iterator))
            adj[u].add(v)
            adj[v].add(u)

        S = int(next(iterator))

        dist = [-1] * (N + 1)
        dist[S] = 0
        queue = deque([S])

        while queue:
            u = queue.popleft()
            current_dist = dist[u]

            if current_dist == 1:
                for v in range(1, N + 1):
                    if dist[v] == -1:
                        dist[v] = 2
                        queue.append(v)
                continue

            neighbors_in_main = adj[u]
            all_nodes = set(range(1, N + 1))
            village_neighbors = all_nodes - neighbors_in_main - {u}

            for v in village_neighbors:
                if dist[v] == -1:
                    dist[v] = current_dist + 1
                    queue.append(v)

        results = []
        for i in range(1, N + 1):
            if i != S:
                results.append(str(dist[i]))

        out_lines.append(" ".join(results))

    print("\n".join(out_lines))

if __name__ == "__main__":
    solve()
